using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class ReleaseValidationMatrixFileStore{private readonly string _path;public ReleaseValidationMatrixFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(ReleaseValidationMatrix value){if(value.LiveAuthorityEnabled)throw new InvalidOperationException("Release validation matrix cannot grant live authority.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public ReleaseValidationMatrix Load(){var v=JsonSerializer.Deserialize<ReleaseValidationMatrix>(File.ReadAllText(_path))??throw new InvalidOperationException("Release validation matrix JSON is invalid.");if(v.LiveAuthorityEnabled)throw new InvalidOperationException("Persisted validation matrix grants live authority.");return v;}}
